using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.PaymentVouchers.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.PaymentVouchers.Commands.CancelPaymentVoucher;public sealed class CancelPaymentVoucherCommandHandler(IPaymentVoucherRepository repository,IApplicationDbContext db):IRequestHandler<CancelPaymentVoucherCommand,Result<PaymentVoucherDto>>{public async Task<Result<PaymentVoucherDto>>Handle(CancelPaymentVoucherCommand request,CancellationToken cancellationToken){var e=await repository.FindForUpdateAsync(request.Id,cancellationToken);if(e is null)return Result.Failure<PaymentVoucherDto>(PaymentVoucherErrors.NotFound);if(e.Status!="Draft")return Result.Failure<PaymentVoucherDto>(PaymentVoucherErrors.NotDraft);e.Cancel();await db.SaveChangesAsync(cancellationToken);return Result.Success(PaymentVoucherDto.FromEntity(e));}}
